var __main = function () {
var nav = getMyVar('fy_nav', 'home'), known = false;
for (var i = 0; i < CATS.length; i++) if (CATS[i].id === nav) known = true;
if (!known) nav = 'home';

for (var c = 0; c < CATS.length; c++) {
    var act = nav === CATS[c].id;
    d.push({
        title: (act ? '✓ ' : '') + CATS[c].n, col_type: 'scroll_button',
        url: $('#noLoading#').lazyRule(function (t) {
            putMyVar('fy_nav', t); putMyVar('fy_p_' + t, '0'); refreshPage(); return 'hiker://empty';
        }, CATS[c].id),
        extra: { backgroundColor: act ? '#FCE4E0' : '#F2F2F2' }
    });
}
d.push({ col_type: 'line_blank' });
d.push({
    title: '搜索', desc: '片名，如：斗罗大陆',
    url: "'hiker://search?rule=" + MY_RULE.title + "&s='+input",
    col_type: 'input'
});
d.push({ col_type: 'line_blank' });

// ================= 首页 =================
if (nav === 'home') {
    var data = cacheGet('fy_home', 300000), lastHtml = '';
    if (!data) {
        var h = get('/', 15000);
        lastHtml = h;
        var blocks = parseBlocks(h), slim = [];
        for (var b = 0; b < blocks.length && slim.length < 6; b++) {
            var items = [];
            for (var k = 0; k < blocks[b].list.length && k < 12; k++) {
                var x = blocks[b].list[k];
                items.push({ id: x.id, name: x.name, pic: x.pic });
            }
            if (items.length >= 3) slim.push({ t: blocks[b].t, items: items });
        }
        if (slim.length) { data = { blocks: slim }; cacheSet('fy_home', data); }
    }
    if (data && data.blocks && data.blocks.length) {
        for (var s2 = 0; s2 < data.blocks.length; s2++) {
            sectionTitle(d, data.blocks[s2].t);
            var cs = cards(data.blocks[s2].items);
            for (var c2 = 0; c2 < cs.length; c2++) d.push(cs[c2]);
        }
    } else {
        failCell(d, '首页', H + '/', lastHtml);
    }
    setResult(d);
    return;
}

// ================= 分类 =================
var pg = parseInt(getMyVar('fy_p_' + nav, '0'), 10) || 0;
if (pg < 0) pg = 0;
var pageNo = pg + 1;

if (nav.indexOf('/label') === 0) {
    var url = H + nav + '/page/' + pageNo + '.html';
    var html = get(url, 15000);
    var ls = parseCards(html);
    sectionTitle(d, catName(nav) + '第 ' + pageNo + ' 页');
    if (!ls.length) failCell(d, catName(nav), url, html);
    else {
        var cc = cards(ls);
        for (var m = 0; m < cc.length; m++) d.push(cc[m]);
        pager(d, pg, ls.length >= 20, 'fy_p_' + nav);
    }
    setResult(d);
    return;
