var api = H + '/index.php/ajax/data?mid=1&tid=' + nav + '&page=' + pageNo + '&limit=20';
var j = getJSON(api, 15000);
if (!j || !j.list) {
    failCell(d, catName(nav), api, j ? JSON.stringify(j).length : '');
} else {
    var list = [], seen = {};
    for (var q = 0; q < j.list.length; q++) {
        var it = j.list[q];
        var vid = String(it.vod_id || '');
        if (!vid || seen[vid]) continue;
        seen[vid] = 1;
        list.push({
            id: vid, name: String(it.vod_name || '').replace(/^\s+|\s+$/g, ''),
            pic: fixPic(it.vod_pic), note: it.vod_remarks || '', year: it.vod_year || ''
        });
    }
    sectionTitle(d, catName(nav) + '第 ' + pageNo + ' 页');
    if (!list.length) {
        d.push({ title: '这一页没有内容', col_type: 'text_1', url: 'hiker://empty' });
    } else {
        var c3 = cards(list);
        for (var z = 0; z < c3.length; z++) d.push(c3[z]);
    }
    var pagecount = parseInt(j.pagecount || 0, 10) || 0;
    var hasNext = pagecount ? (pageNo < pagecount) : (list.length >= 20);
    pager(d, pg, hasNext, 'fy_p_' + nav);
}
siteLine(d);
setResult(d);
};
__main();

