var key = '';
var m = myUrl.match(/[?&](?:q|wd|kw|s|search|keyword|word|name|key)=([^&#]+)/);
key = m ? decodeURIComponent(m[1]) : '';
key = key.replace(/^\s+|\s+$/g, '');
if (!key) {
    d.push({ title: '没拿到搜索词', col_type: 'text_1', url: 'hiker://empty' });
    setResult(d);
    return;
}

var pg = parseInt(getMyVar('fy_sp_' + key, '0'), 10) || 0;
if (pg < 0) pg = 0;
var pageNo = pg + 1;

var api = H + '/search/-------------.html?wd=' + encodeURIComponent(key) + (pageNo > 1 ? ('&page=' + pageNo) : '');
var hd = { 'User-Agent': UA, 'Referer': H + '/', 'Accept-Language': 'zh-CN,zh;q=0.9' };
var ck = getMyVar('fy_ck', '');
if (ck) hd['Cookie'] = ck;
var html = '';
try { html = String(request(api, { headers: hd, timeout: 15000 }) || ''); } catch (e) { html = ''; }
// 有些 IP 直接打搜索页会回 500「System Error」，先摸一次首页拿到会话 cookie 再试，
// 拿到后就是正常的验证码页。这一步只是为了不把「被拦」误判成「没搜到」。
if (!html || html.indexOf('System Error') > -1) {
    try { request(H + '/', { headers: { 'User-Agent': UA, 'Referer': H + '/' }, timeout: 10000 }); } catch (e) { }
    try { ck = String(getCookie(H + '/') || ''); } catch (e2) { ck = ''; }
    if (ck) { putMyVar('fy_ck', ck); hd['Cookie'] = ck; }
    try { html = String(request(api, { headers: hd, timeout: 15000 }) || ''); } catch (e3) { html = ''; }
}

// 只认 ASCII 标记，避免页面编码不一致时认不出验证码页（这几个串在拦页面里一定有）
var shielded = (html && (html.indexOf('系统安全验证') > -1 || html.indexOf('访问此数据需要输入验证码') > -1
    || html.indexOf('mac_verify') > -1 || html.indexOf('captcha.php?type=code') > -1
    || html.indexOf('System Error') > -1 || html.length < 2000));

if (shielded) {
    // 主页面只留一个入口，点开是独立的验证码页（那里图片铺满整宽、输入框真能打字）。
    // 这是照饺子点播的做法：验证界面必须在 lazyRule 子页面里渲染。
    putMyVar('fy_host', H);
    var lastFail = 0;
    try { lastFail = parseInt(getMyVar('fy_capfail', '0'), 10) || 0; } catch (e) { lastFail = 0; }
    if (nowMs() - lastFail < 180000) {
        d.push({ title: '上次验证没通过，重新点下面这条再试', col_type: 'text_1', url: 'hiker://empty' });
    }
    d.push(capCard());
    setResult(d);
    return;
}

var list = parseCards(html);
if (!list.length) {
    d.push({
        title: html ? ('没搜到「' + key + '」') : '没取到搜索结果（0 字节）',
        col_type: 'text_1', url: 'hiker://empty'
    });
    d.push({
        title: '重试', col_type: 'scroll_button',
        url: $('#noLoading#').lazyRule(function () { refreshPage(); return 'hiker://empty'; }),
        extra: { backgroundColor: '#FCE4E0' }
    });
} else {
    var cs = cards(list);
    for (var c2 = 0; c2 < cs.length; c2++) d.push(cs[c2]);
    pager(d, pg, list.length >= 18, 'fy_sp_' + key, '1');
}
setResult(d);
};
