var HOSTS = ['https://www.zzztool.com', 'https://www.cadkssb.com'];
var UA = 'Mozilla/5.0 (Linux; Android 15; Pixel 9) AppleWebKit/537.36 Chrome/150.0.0.0 Mobile';
var CATS = [
    { id: 'home', n: '首页' },
    { id: '2', n: '电视剧' },
    { id: '1', n: '电影' },
    { id: '4', n: '动漫' },
    { id: '3', n: '综艺' },
    { id: '5', n: '短剧' },
    { id: '/label/qq', n: '腾讯' },
    { id: '/label/bli', n: 'B站' },
    { id: '/label/youku', n: '优酷' }
];
// 线路排序：4K 在前，其次是主流站，自营线兜底
var LINE_ORDER = ['至臻4k', '蓝光2k', '蓝光', '爱奇艺', 'B站', '腾讯', '优酷', '自营t', '自营y', '自营r'];

function nowMs() { try { return new Date().getTime(); } catch (e) { return 0; } }
function clean(s) {
    return String(s == null ? '' : s).replace(/<[^>]+>/g, '').replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&')
        .replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&#39;/g, "'").replace(/\s+/g, ' ').replace(/^\s+|\s+$/g, '');
}
function catName(id) { for (var i = 0; i < CATS.length; i++) if (CATS[i].id === id) return CATS[i].n; return '首页'; }
function hostGet() { return getMyVar('fy_host', HOSTS[0]); }
function hostSet(h) { try { putMyVar('fy_host', h); } catch (e) { } }
function fixPic(u, h) {
    u = String(u || '');
    if (!u) return '';
    if (u.indexOf('//') === 0) return 'https:' + u;
    if (u.charAt(0) === '/') return (h || hostGet()) + u;
    return u;
}

// 请求：主域名失败自动换备用域名（旗帜站常换域名，这里不做发布页探测，减少一次往返）
var H = hostGet();
function req(url, opt) {
    opt = opt || {};
    var t = '';
    for (var i = 0; i < 2; i++) {
        try {
            t = String(request(url, {
                method: opt.method || 'GET',
                body: opt.body || '',
                headers: opt.headers || {
                    'User-Agent': UA,
                    'Accept': 'text/html,application/xhtml+xml,*/*;q=0.8',
                    'Accept-Language': 'zh-CN,zh;q=0.9',
                    'Referer': H + '/'
                },
                timeout: opt.timeout || 12000
            }) || '');
        } catch (e) { t = ''; }
        if (t) return t;
    }
    return t;
}
function getUrl(u) {
    if (!u) return '';
    if (u.indexOf('http') === 0) return u;
    if (u.charAt(0) === '/') return H + u;
    return H + '/' + u;
}
// 带域名切换的取页：当前域名拿不到就换另一个
function get(u, to) {
    var url = getUrl(u), t = req(url, { timeout: to || 12000 });
    if (t && t.length > 300) return t;
    for (var i = 0; i < HOSTS.length; i++) {
        if (HOSTS[i] === H) continue;
        var u2 = (u.indexOf('http') === 0) ? String(u).replace(H, HOSTS[i]) : (HOSTS[i] + (u.charAt(0) === '/' ? u : '/' + u));
        var t2 = req(u2, { timeout: to || 12000 });
        if (t2 && t2.length > 300) { H = HOSTS[i]; hostSet(H); return t2; }
    }
    return t;
}
function getJSON(u, to) {
    var t = get(u, to);
    if (!t) return null;
    try { return JSON.parse(t); } catch (e) { return null; }
}
function cacheGet(k, ttl) {
    try {
        var o = JSON.parse(getMyVar(k, '{}'));
        if (o && o.t && o.d && (nowMs() - o.t) < ttl) return o.d;
    } catch (e) { }
    return null;
}
function cacheSet(k, d) {
    try {
        var s = JSON.stringify({ t: nowMs(), d: d });
        if (s.length < 60000) putMyVar(k, s);
    } catch (e) { }
}

// ---- 卡片解析（首页大卡 / 分类小卡两种模板通用）----
function parseCards(html) {
    var s = String(html || ''), out = [], seen = {};
    if (!s) return out;
    var re = /<a[^>]+href="\/detail\/(\d+)\.html"[^>]*>/g, m, marks = [];
    while ((m = re.exec(s)) !== null) marks.push({ at: m.index, id: m[1], tag: m[0] });
    for (var i = 0; i < marks.length; i++) {
        var id = marks[i].id;
        if (seen[id]) continue;
        seen[id] = 1;
        var seg = s.substring(marks[i].at, (i + 1 < marks.length) ? marks[i + 1].at : Math.min(s.length, marks[i].at + 3000));
        var name = '';
        var tm = marks[i].tag.match(/\btitle="([^"]*)"/);
        if (tm) name = clean(tm[1]);
        if (!name) { tm = seg.match(/<strong[^>]*>([\s\S]{1,60}?)<\/strong>/); if (tm) name = clean(tm[1]); }
        if (!name) { tm = seg.match(/alt="([^"]*)"/); if (tm) name = clean(tm[1]); }
        if (!name) continue;
        var pic = '';
        tm = seg.match(/(?:data-src|data-original)="([^"]+)"/);
        if (tm) pic = tm[1];
        if (!pic) { tm = seg.match(/<img[^>]+src="([^"]+)"/); if (tm && tm[1].indexOf('null.jpg') < 0) pic = tm[1]; }
        var note = '';
        tm = seg.match(/class="module-item-note"[^>]*>([\s\S]{0,40}?)</);
        if (tm) note = clean(tm[1]);
        if (!note) { tm = seg.match(/class="module-card-item-class"[^>]*>([\s\S]{0,20}?)</); if (tm) note = clean(tm[1]); }
        out.push({ id: id, name: name, pic: fixPic(pic), note: note });
    }
    return out;
}

// ---- 首页板块：站点首页一次请求里就有多组 .module-items，按块拆开 ----
function parseBlocks(html) {
    var s = String(html || ''), out = [], marks = [], re = /<div class="module-items[^"]*"/g, m;
    while ((m = re.exec(s)) !== null) marks.push(m.index);
    if (!marks.length) {
        var one = parseCards(s);
        if (one.length) out.push({ t: '最新更新', list: one });
        return out;
    }
    for (var i = 0; i < marks.length && out.length < 8; i++) {
        var seg = s.substring(marks[i], (i + 1 < marks.length) ? marks[i + 1] : s.length);
        var arr = parseCards(seg);
        if (!arr.length) continue;
        var pre = s.substring(Math.max(0, marks[i] - 2500), marks[i]), t = '';
        var rh = /<h2 class="module-title">([^<]{1,24})/g, mh, last = '';
        while ((mh = rh.exec(pre)) !== null) last = clean(mh[1]);
        out.push({ t: last || ('板块' + (out.length + 1)), list: arr });
    }
    return out;
}

function epNo(t) { var m = String(t || '').match(/\d+/); return m ? parseInt(m[0], 10) : 0; }

// ---- 详情 ----
function parseDetail(html) {
    var s = String(html || '');
    var o = { name: '', pic: '', info: '', intro: '', lines: [] };
    var m = s.match(/<div class="module-info-heading">[\s\S]{0,400}?<h1[^>]*>([\s\S]{1,120}?)<\/h1>/);
    if (!m) m = s.match(/<h1[^>]*>([\s\S]{1,120}?)<\/h1>/);
    if (m) o.name = clean(m[1]);
    m = s.match(/class="module-item-pic"[\s\S]{0,300}?data-src="([^"]+)"/);
    if (!m) m = s.match(/data-src="([^"]+\.(?:webp|jpg|png)[^"]*)"/);
    if (m) o.pic = fixPic(m[1]);
    var infos = [], ri = /<div class="module-info-item-title">([\s\S]{1,20}?)<\/div>\s*<div class="module-info-item-content">([\s\S]{1,200}?)<\/div>/g, mi;
    while ((mi = ri.exec(s)) !== null) {
        var k = clean(mi[1]), v = clean(mi[2]);
        if (v) infos.push(k + ' ' + v);
    }
    o.info = infos.join('　');
    m = s.match(/class="module-info-introduction-content"[^>]*>([\s\S]{1,1200}?)<\/div>/);
    if (m) o.intro = clean(m[1]).substring(0, 400);

    var tabs = [], rt = /mx-anthology-tab-label">([^<]{1,20})</g, mt;
    while ((mt = rt.exec(s)) !== null) tabs.push(clean(mt[1]));
    // 注意：外层容器是 mx-anthology-panels（复数），按 'mx-anthology-panel' 切会把容器也算进去，
    // 结果线路名整体错位、少一条线。这里跳过以 s 开头的碎块（容器）。
    var rawPanels = s.split('<div class="mx-anthology-panel'), panels = [];
    for (var rp = 1; rp < rawPanels.length; rp++) {
        if (rawPanels[rp].charAt(0) === 's') continue;
        panels.push(rawPanels[rp]);
    }
    var used = {}, lines = [];
    for (var i = 0; i < panels.length && i < tabs.length; i++) {
        var eps = [], re2 = /<a[^>]+href="(\/play\/[^"]+?\.html)"[^>]*>([\s\S]{1,40}?)<\/a>/g, m2;
        while ((m2 = re2.exec(panels[i])) !== null) {
            var nm = clean(m2[2]);
            if (!nm) continue;
            eps.push({ n: nm, u: m2[1] });
        }
        if (!eps.length) continue;
        // 站点选集默认从大到小（第34集在前），这里按集号判断，倒着列的就翻正
        var n1 = epNo(eps[0].n), n2 = epNo(eps[eps.length - 1].n);
        if (n1 && n2 && n1 > n2) eps.reverse();
        var ln = tabs[i] || ('线路' + (i + 1));
        used[ln] = (used[ln] || 0) + 1;
        if (used[ln] > 1) ln = ln + '-' + used[ln];
        lines.push({ n: ln, eps: eps, i: i });
    }
    // 线路排序：至臻4k → 蓝光2k → 主流站 → 自营（同名保持页面顺序）
    for (var a = 0; a < lines.length; a++) {
        var ord = 99;
        for (var b = 0; b < LINE_ORDER.length; b++) if (lines[a].n.indexOf(LINE_ORDER[b]) === 0) { ord = b; break; }
        lines[a].ord = ord;
    }
    lines.sort(function (x, y) { return (x.ord - y.ord) || (x.i - y.i); });
