// ---- 版式 ----
function cards(list) {
    var d = [];
    for (var i = 0; i < list.length; i++) {
        var it = list[i];
        d.push({
            title: it.name,
            desc: '',
            pic_url: it.pic,
            url: 'hiker://page/detail?id=' + it.id + '#immersiveTheme#',
            col_type: 'movie_3'
        });
