            }, iVar),
            extra: { backgroundColor: '#F2F2F2' }
        });
    }
    if (hasNext) {
        d.push({
            title: '下一页 ›', col_type: 'scroll_button',
            url: $('#noLoading#').lazyRule(function (v) {
                putMyVar(v, String(parseInt(getMyVar(v, '0'), 10) + 1)); refreshPage(); return 'hiker://empty';
            }, iVar),
            extra: { backgroundColor: '#F2F2F2' }
        });
    }
}
function failCell(d, what, url, html) {
    d.push({
        title: what + '没取到内容',
        desc: '请求 ' + url + '　返回 ' + String(html || '').length + ' 字节',
        col_type: 'text_1', url: 'hiker://empty'
    });
