// 站点网址固定作为页面最后一块（用户定的排版规矩：网址之后不再跟内容）
function siteLine(d) {
    d.push({ col_type: 'line_blank' });
    d.push({ title: H, url: 'hiker://empty', col_type: 'text_1' });
}

// 过验证：lazyRule 独立作用域，只用参数与本页全局函数
// 照着饺子点播的做法：验证码界面不放在主页面里，而是主页面给一个入口，点开进入一个
// lazyRule 子页面——在那种页面里 pic_1_full 会铺满整宽、input 才是真正可编辑的输入框
// （这是 2026-11-12 用户拿饺子点播截图对照后确认的差异）。
// 里面的函数体必须是自包含的：只能用 MyVar 和海阔给的全局（fetch/getCookie/putMyVar…），
// 不能引用页面级变量。
function capCard() {
    return {
        title: '点击输入验证码解锁搜索',
        col_type: 'text_center_1',
        // 注意：空选择器（$ 里给空串）会被海阔当 URL 去请求，报
        //「Expected URL scheme 'http' or 'https' but no colon was found」→ 必须给 #noLoading#
        url: $('hiker://empty').rule(function () {
            var dd = [];
            try {
            var h = getMyVar('fy_host', 'https://www.zzztool.com');
            var ua2 = 'Mozilla/5.0 (Linux; Android 15; Pixel 9) AppleWebKit/537.36 Chrome/150.0.0.0 Mobile';
            var imgUrl = h + '/captcha.php?type=code&r=' + Math.random();
